import ast
from pathlib import Path
root = Path('.')
for path in sorted(root.rglob('*.py')):
    if any(part in {'.venv','staticfiles','__pycache__'} for part in path.parts):
        continue
    try:
        tree = ast.parse(path.read_text(encoding='utf-8'))
    except Exception as exc:
        print(f'ERROR {path}: {exc}')
        continue
    missing = []
    if not ast.get_docstring(tree):
        missing.append('modulo')
    for node in ast.walk(tree):
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)) and not ast.get_docstring(node):
            missing.append(f'{node.__class__.__name__}:{node.name}:{node.lineno}')
    if missing:
        print(f'{path}: ' + ', '.join(missing))
