/* =====================================================================
   Global Exchange — sistema de diseño del back-office
   ---------------------------------------------------------------------
   Enfoque "libro mayor" (ledger-flat): bordes en vez de sombras,
   numeración tabular para cifras e identificadores, un solo acento
   (bronce) reservado para acciones primarias y el teal reservado para
   indicar "esto está activo/seleccionado ahora mismo" (cliente activo,
   ítem de navegación actual). Nada de tarjetas-SaaS genéricas.
   ===================================================================== */

:root {
    --ge-ink: #101826;
    --ge-ink-soft: #1c2740;
    --ge-paper: #EEF1F4;
    --ge-surface: #FFFFFF;
    --ge-border: #DDE2E8;
    --ge-text: #1A2333;
    --ge-text-muted: #5B6478;
    --ge-teal: #0E7C7B;
    --ge-teal-soft: #E4F2F1;
    --ge-brass: #B3812E;
    --ge-brass-dark: #8F6623;
    --ge-brass-soft: #F5ECDA;
    --ge-brick: #A8442C;
    --ge-brick-soft: #F7E4DF;
    --ge-radius: 8px;
    --ge-radius-sm: 5px;
    --sidebar-width: 248px;
    --topbar-height: 68px;
}

html, body {
    height: 100%;
}

body {
    font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    background-color: var(--ge-paper);
    color: var(--ge-text);
    font-size: 15px;
    line-height: 1.5;
}

h1, h2, h3, h4, h5 {
    font-weight: 650;
    letter-spacing: -0.01em;
    color: var(--ge-ink);
}

a {
    color: var(--ge-teal);
}

/* Cifras, identificadores y montos: numeración tabular para que
   columnas de números alineen entre sí, como en un libro contable. */
.ge-num, table td, .ge-app-shell .badge {
    font-variant-numeric: tabular-nums;
}

/* ---------------------------------------------------------------
   Estructura de la aplicación (shell): sidebar fija + topbar + main
   --------------------------------------------------------------- */
.ge-app-shell {
    display: flex;
    min-height: 100vh;
}

.ge-sidebar {
    width: var(--sidebar-width);
    flex-shrink: 0;
    background: var(--ge-ink);
    color: #C9D2E3;
    display: flex;
    flex-direction: column;
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
}

.ge-sidebar__brand {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 20px 20px 16px;
    color: #fff;
    text-decoration: none;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.ge-sidebar__brand-mark {
    width: 32px;
    height: 32px;
    border-radius: var(--ge-radius-sm);
    background: var(--ge-brass);
    color: var(--ge-ink);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 14px;
    flex-shrink: 0;
}

.ge-sidebar__brand-text {
    font-weight: 700;
    font-size: 15px;
    line-height: 1.2;
}
.ge-sidebar__brand-text small {
    display: block;
    font-weight: 400;
    font-size: 11px;
    color: #8894AC;
}

.ge-sidebar__section-label {
    padding: 18px 20px 6px;
    font-size: 11px;
    color: #6E7A93;
    font-weight: 600;
}

.ge-sidebar__nav {
    list-style: none;
    margin: 0;
    padding: 4px 10px;
}

.ge-sidebar__link {
    display: flex;
    align-items: center;
    gap: 11px;
    padding: 9px 12px;
    border-radius: var(--ge-radius-sm);
    color: #C9D2E3;
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    border-left: 3px solid transparent;
    margin-bottom: 2px;
}

.ge-sidebar__link i {
    font-size: 16px;
    width: 18px;
    text-align: center;
    color: #8894AC;
}

.ge-sidebar__link:hover {
    background: rgba(255,255,255,0.06);
    color: #fff;
}

.ge-sidebar__link.is-active {
    background: rgba(14, 124, 123, 0.25);
    color: #fff;
    border-left-color: var(--ge-teal);
}

.ge-sidebar__link.is-active i {
    color: #6FD6D4;
}

.ge-sidebar__footer {
    margin-top: auto;
    padding: 16px 20px;
    font-size: 12px;
    color: #6E7A93;
    border-top: 1px solid rgba(255,255,255,0.08);
}

/* ---------------------------------------------------------------
   Columna principal: topbar + contenido
   --------------------------------------------------------------- */
.ge-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.ge-topbar {
    height: var(--topbar-height);
    background: var(--ge-surface);
    border-bottom: 1px solid var(--ge-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 0 24px;
    position: sticky;
    top: 0;
    z-index: 20;
}

.ge-topbar__toggle {
    display: none;
    border: 1px solid var(--ge-border);
    background: var(--ge-surface);
    border-radius: var(--ge-radius-sm);
    width: 36px;
    height: 36px;
    align-items: center;
    justify-content: center;
    color: var(--ge-ink);
}

/* Pastilla de contexto: cliente en cuyo nombre se está operando */
.ge-contexto-cliente {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px 6px 8px;
    border-radius: 999px;
    background: var(--ge-teal-soft);
    border: 1px solid #BFE0DF;
    color: var(--ge-teal);
    font-size: 13px;
    font-weight: 600;
    text-decoration: none;
}
.ge-contexto-cliente .ge-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--ge-teal);
