    color: var(--ge-teal);
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
}

.ge-form-grid {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.ge-form-field {
    display: flex;
