"""Formularios para registrar, actualizar y simular cotizaciones."""

from django import forms
from django.core.validators import RegexValidator
from .models import CalculoOperacion, ConfiguracionOperacion, Cotizacion, Divisa


class CalculoOperacionForm(forms.Form):
    """Valida tipo, monto y divisas de una operación cambiaria cruzada."""

    tipo = forms.ChoiceField(
        choices=CalculoOperacion.TIPO_CHOICES,
        widget=forms.HiddenInput(),
    )
    monto = forms.DecimalField(
        label='Monto de la operación',
        min_value=0.01,
        max_digits=18,
        decimal_places=2,
        widget=forms.NumberInput(attrs={'step': '0.01', 'min': '0.01', 'class': 'form-control ge-form-control'}),
    )
    divisa_origen = forms.ChoiceField(
        label='Divisa de origen',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )
    divisa_destino = forms.ChoiceField(
        label='Divisa de destino',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )

    def __init__(self, *args, tipo=None, **kwargs):
        """Carga divisas activas y fija el tipo de operación solicitado."""
        super().__init__(*args, **kwargs)
        tipo_inicial = tipo or self.data.get('tipo') or CalculoOperacion.TIPO_COMPRA
        self.fields['tipo'].initial = tipo_inicial
        self.fields['tipo'].disabled = True
        origen = self.data.get('divisa_origen') if self.is_bound else None
        destino = self.data.get('divisa_destino') if self.is_bound else None
        self.fields['divisa_origen'].choices = self.opciones_divisas(excluir=destino)
        self.fields['divisa_destino'].choices = self.opciones_divisas(excluir=origen)

    @staticmethod
    def _divisa_guarani_implicit():
        """Construye el PYG implícito cuando no está registrado."""
        return Divisa(codigo='PYG', nombre='Guaraní', simbolo='₲', activa=True)

    @classmethod
    def opciones_divisas(cls, excluir=None):
        """Devuelve divisas activas, excluyendo la elegida en el otro campo."""
        divisas = list(Divisa.objects.filter(activa=True).order_by('codigo'))
        opciones = [
            ('PYG' if divisa.codigo == 'PYG' else str(divisa.pk), f'{divisa.nombre} ({divisa.codigo})')
            for divisa in divisas
            if str(divisa.pk) != str(excluir) and not (divisa.codigo == 'PYG' and excluir == 'PYG')
        ]
        if excluir != 'PYG' and not any(valor == 'PYG' for valor, _ in opciones):
            opciones.insert(0, ('PYG', 'Guaraní (PYG)'))
        return opciones

    def clean_tipo(self):
        """Valida que el tipo sea compra o venta."""
        tipo = self.cleaned_data['tipo']
        if tipo not in {CalculoOperacion.TIPO_COMPRA, CalculoOperacion.TIPO_VENTA}:
            raise forms.ValidationError('El tipo de operación no es válido.')
        return tipo

    def _resolver_divisa(self, valor):
        """Resuelve una divisa activa o la representación base PYG."""
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_divisa_origen(self):
        """Resuelve y valida la divisa de origen."""
        return self._resolver_divisa(self.cleaned_data['divisa_origen'])

    def clean_divisa_destino(self):
        """Resuelve y valida la divisa de destino."""
        return self._resolver_divisa(self.cleaned_data['divisa_destino'])

    def clean(self):
        """Impide operar entre la misma divisa."""
        cleaned_data = super().clean()
        origen = cleaned_data.get('divisa_origen')
        destino = cleaned_data.get('divisa_destino')
        if origen and destino and origen.codigo == destino.codigo:
            raise forms.ValidationError('La divisa de origen y destino deben ser diferentes.')
        return cleaned_data


class SimulacionDivisasForm(forms.Form):
    """Valida tipo, monto y divisas para simular compra o venta."""

    tipo = forms.ChoiceField(
        label='Tipo de operación',
        choices=CalculoOperacion.TIPO_CHOICES,
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )

    monto = forms.DecimalField(
        label='Monto a convertir',
        min_value=0,
        max_digits=18,
        decimal_places=2,
        widget=forms.NumberInput(attrs={'step': '0.01', 'min': '0.01', 'class': 'form-control ge-form-control'}),
    )
    divisa_origen = forms.ChoiceField(
        label='Divisa origen',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )
    divisa_destino = forms.ChoiceField(
        label='Divisa destino',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )

    @staticmethod
    def _divisa_guarani_implicit():
        """Construye la divisa PYG implícita cuando no existe en la base."""
        return Divisa(codigo='PYG', nombre='Guaraní', simbolo='₲', activa=True)

    @classmethod
    def opciones_divisas(cls, excluir=None):
        """Devuelve divisas activas excluyendo la elegida en el otro campo."""
        divisas_activas = list(Divisa.objects.filter(activa=True).order_by('codigo'))
        opciones = []

        for divisa in divisas_activas:
            valor = 'PYG' if divisa.codigo == 'PYG' else str(divisa.pk)
            if valor != str(excluir):
                opciones.append((valor, f'{divisa.nombre} ({divisa.codigo})'))

        if excluir != 'PYG' and not any(opt[0] == 'PYG' for opt in opciones):
            opciones.insert(0, ('PYG', 'Guaraní (PYG)'))

        return opciones

    def __init__(self, *args, **kwargs):
        """Inicializa el formulario con las opciones vigentes de divisas."""
        super().__init__(*args, **kwargs)
        origen = self.data.get('divisa_origen') if self.is_bound else None
        destino = self.data.get('divisa_destino') if self.is_bound else None
        self.fields['divisa_origen'].choices = self.opciones_divisas(excluir=destino)
        self.fields['divisa_destino'].choices = self.opciones_divisas(excluir=origen)

    def clean_tipo(self):
        """Valida que la simulación sea de compra o venta."""
        tipo = self.cleaned_data['tipo']
        if tipo not in {CalculoOperacion.TIPO_COMPRA, CalculoOperacion.TIPO_VENTA}:
            raise forms.ValidationError('El tipo de operación no es válido.')
        return tipo

    def clean_divisa_origen(self):
        """Convierte y valida la divisa seleccionada como origen."""
        valor = self.cleaned_data['divisa_origen']
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_divisa_destino(self):
        """Convierte y valida la divisa seleccionada como destino."""
        valor = self.cleaned_data['divisa_destino']
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_monto(self):
        """Verifica que el monto de conversión sea positivo."""
        monto = self.cleaned_data['monto']
        if monto <= 0:
            raise forms.ValidationError('El monto debe ser mayor que cero.')
        return monto

    def clean(self):
        """Evita que la conversión use la misma divisa en ambos extremos."""
        cleaned_data = super().clean()
        origen = cleaned_data.get('divisa_origen')
        destino = cleaned_data.get('divisa_destino')

        if origen and destino:
            if getattr(origen, 'codigo', None) == getattr(destino, 'codigo', None):
            raise forms.ValidationError('La divisa de origen y destino deben ser diferentes.')

        return cleaned_data


class ConfiguracionOperacionForm(forms.ModelForm):
    """Permite a roles autorizados modificar la comisión de operaciones."""

    class Meta:
        """Define el único campo editable de la configuración."""
        model = ConfiguracionOperacion
        fields = ['comision_porcentaje']
        labels = {'comision_porcentaje': 'Comisión (%)'}
        widgets = {
            'comision_porcentaje': forms.NumberInput(
                attrs={'step': '0.001', 'min': '0', 'class': 'form-control ge-form-control'}
            ),
        }

    def clean_comision_porcentaje(self):
        """Rechaza comisiones negativas o superiores al cien por ciento."""
        valor = self.cleaned_data['comision_porcentaje']
        if valor < 0 or valor > 100:
            raise forms.ValidationError('La comisión debe estar entre 0% y 100%.')
        return valor


class DivisaForm(forms.ModelForm):
    """Valida los datos básicos de una divisa administrable."""
    codigo = forms.CharField(
        label='Código ISO (Ej. USD, EUR, PYG)',
        max_length=3,
        validators=[
            RegexValidator(
                regex=r'^[A-Z]{3}$',
                message='El código debe tener exactamente 3 letras mayúsculas (ISO 4217).',
            )
        ],
    )
    nombre = forms.CharField(label='Nombre de la divisa', max_length=50)
    simbolo = forms.CharField(label='Símbolo (Ej. $, €)', max_length=5)
    class Meta:
        """Define el modelo y los campos editables de la divisa."""
        model = Divisa
        fields = ['codigo', 'nombre', 'simbolo']

    def clean_codigo(self):
        """Normaliza el código ISO y controla que no esté duplicado."""
        codigo = self.cleaned_data['codigo'].strip().upper()
        duplicado = Divisa.objects.filter(codigo__iexact=codigo)
        if self.instance.pk:
            duplicado = duplicado.exclude(pk=self.instance.pk)
        if duplicado.exists():
            raise forms.ValidationError('Ya existe una divisa con este código ISO.')
        return codigo

    def clean_nombre(self):
        """Rechaza nombres de divisa vacíos."""
        nombre = self.cleaned_data['nombre'].strip()
        if not nombre:
            raise forms.ValidationError('El nombre de la divisa es obligatorio.')
        return nombre

    def clean_simbolo(self):
        """Rechaza símbolos de divisa vacíos."""
        simbolo = self.cleaned_data['simbolo'].strip()
        if not simbolo:
            raise forms.ValidationError('El símbolo de la divisa es obligatorio.')
        return simbolo


class CotizacionForm(forms.ModelForm):
    """Valida las tasas de compra y venta de una cotización."""
    class Meta:
        """Define los campos y etiquetas editables de la cotización."""
        model = Cotizacion
        fields = ['tasa_compra', 'tasa_venta']
        labels = {
            'tasa_compra': 'Precio de compra',
            'tasa_venta': 'Precio de venta',
        }
        widgets = {
            'tasa_compra': forms.NumberInput(attrs={'step': '0.01', 'min': '0.01'}),
            'tasa_venta': forms.NumberInput(attrs={'step': '0.01', 'min': '0.01'}),
        }

    def clean(self):
        """Comprueba que ambas tasas sean positivas y estén ordenadas."""
        cleaned_data = super().clean()
        compra = cleaned_data.get('tasa_compra')
        venta = cleaned_data.get('tasa_venta')

        if compra is not None and compra <= 0:
            self.add_error('tasa_compra', 'El precio de compra debe ser mayor que cero.')
        if venta is not None and venta <= 0:
            self.add_error('tasa_venta', 'El precio de venta debe ser mayor que cero.')
        if compra is not None and venta is not None and compra > venta:
            raise forms.ValidationError(
                'El precio de compra no puede ser mayor que el precio de venta.'
            )
        return cleaned_data

"""Vistas para consultar, administrar y simular cotizaciones de divisas."""

from datetime import timedelta
from decimal import Decimal, ROUND_HALF_UP

from django.conf import settings
from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.contrib.auth.mixins import LoginRequiredMixin, UserPassesTestMixin
from django.shortcuts import get_object_or_404, redirect, render
from django.urls import reverse, reverse_lazy
from django.utils import timezone
from django.views import View
from django.views.generic import CreateView, ListView, TemplateView, UpdateView

from apps.authentication.forms import CausaBajaForm
from apps.authentication.models import HistorialBaja
from apps.divisas.forms import (
    CalculoOperacionForm,
    ConfiguracionOperacionForm,
    CotizacionForm,
    DivisaForm,
    SimulacionDivisasForm,
)
from apps.divisas.models import CalculoOperacion, ConfiguracionOperacion, Cotizacion, Divisa


def _obtener_cotizacion_operacion(divisa):
    """Obtiene compra y venta vigentes de una divisa o tasas unitarias de PYG."""
    if divisa.codigo == 'PYG':
        return Decimal('1.00'), Decimal('1.00'), None
    cotizacion = divisa.ultima_cotizacion
    if not cotizacion:
        raise ValueError(f'La divisa {divisa.codigo} no tiene cotización disponible.')
    return cotizacion.tasa_compra, cotizacion.tasa_venta, cotizacion


def _calcular_importe_operacion(tipo, monto, tasa_origen, tasa_destino, porcentaje):
    """Calcula el cruce, comisión y total entre dos divisas."""
    if tipo == CalculoOperacion.TIPO_COMPRA:
        tasa_origen_aplicada = tasa_origen
        tasa_destino_aplicada = tasa_destino
    else:
        tasa_origen_aplicada = tasa_destino
        tasa_destino_aplicada = tasa_origen
    tasa_aplicada = tasa_origen_aplicada / tasa_destino_aplicada
    bruto = (monto * tasa_aplicada).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    comision = (bruto * porcentaje / Decimal('100')).quantize(
        Decimal('0.01'), rounding=ROUND_HALF_UP
    )
    monto_final = bruto + comision if tipo == CalculoOperacion.TIPO_COMPRA else bruto - comision
    return tasa_aplicada, tasa_origen_aplicada, tasa_destino_aplicada, comision, monto_final


class TasasVigentesListView(LoginRequiredMixin, UserPassesTestMixin, ListView):
    """Lista las tasas de las divisas activas para roles operativos."""
    model = Divisa
    template_name = 'divisas/tasas_vigentes.html'
    context_object_name = 'divisas'

