def _obtener_cotizacion_operacion(divisa):
    """Obtiene compra y venta vigentes de una divisa o tasas unitarias de PYG."""
    if divisa.codigo == 'PYG':
        return Decimal('1.00'), Decimal('1.00'), None
    cotizacion = divisa.ultima_cotizacion
    if not cotizacion:
        raise ValueError(f'La divisa {divisa.codigo} no tiene cotización disponible.')
    return cotizacion.tasa_compra, cotizacion.tasa_venta, cotizacion


def _calcular_importe_operacion(tipo, monto, tasa_origen_aplicada, tasa_destino_aplicada, porcentaje):
    """Calcula el cruce, comisión y total entre dos divisas."""
    tasa_aplicada = tasa_origen_aplicada / tasa_destino_aplicada
    bruto = (monto * tasa_aplicada).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    comision = (bruto * porcentaje / Decimal('100')).quantize(
        Decimal('0.01'), rounding=ROUND_HALF_UP
    )
    monto_final = bruto + comision if tipo == CalculoOperacion.TIPO_COMPRA else bruto - comision
    return tasa_aplicada, tasa_origen_aplicada, tasa_destino_aplicada, comision, monto_final


