class CalculoOperacionForm(forms.Form):
    """Valida tipo, monto y divisas de una operación cambiaria cruzada."""

    tipo = forms.ChoiceField(
        choices=CalculoOperacion.TIPO_CHOICES,
        widget=forms.HiddenInput(),
    )
    monto = forms.DecimalField(
        label='Monto de la operación',
        min_value=0.01,
        max_digits=18,
        decimal_places=2,
        widget=forms.NumberInput(attrs={'step': '0.01', 'min': '0.01', 'class': 'form-control ge-form-control'}),
    )
    divisa_origen = forms.ChoiceField(
        label='Divisa de origen',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )
    divisa_destino = forms.ChoiceField(
        label='Divisa de destino',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )

    def __init__(self, *args, tipo=None, **kwargs):
        """Carga divisas activas y fija el tipo de operación solicitado."""
        super().__init__(*args, **kwargs)
        tipo_inicial = tipo or self.data.get('tipo') or CalculoOperacion.TIPO_COMPRA
        self.fields['tipo'].initial = tipo_inicial
        self.fields['tipo'].disabled = True
        origen = self.data.get('divisa_origen') if self.is_bound else None
        destino = self.data.get('divisa_destino') if self.is_bound else None
        self.fields['divisa_origen'].choices = self.opciones_divisas(excluir=destino)
        self.fields['divisa_destino'].choices = self.opciones_divisas(excluir=origen)

    @staticmethod
    def _divisa_guarani_implicit():
        """Construye el PYG implícito cuando no está registrado."""
        return Divisa(codigo='PYG', nombre='Guaraní', simbolo='₲', activa=True)

    @classmethod
    def opciones_divisas(cls, excluir=None):
        """Devuelve divisas activas, excluyendo la elegida en el otro campo."""
        divisas = list(Divisa.objects.filter(activa=True).order_by('codigo'))
        opciones = [('', 'Seleccione una divisa')]
        opciones.extend([
            ('PYG' if divisa.codigo == 'PYG' else str(divisa.pk), f'{divisa.nombre} ({divisa.codigo})')
            for divisa in divisas
            if str(divisa.pk) != str(excluir) and not (divisa.codigo == 'PYG' and excluir == 'PYG')
        ])
        if excluir != 'PYG' and not any(valor == 'PYG' for valor, _ in opciones):
            opciones.insert(1, ('PYG', 'Guaraní (PYG)'))
        return opciones

    def clean_tipo(self):
        """Valida que el tipo sea compra, venta o cruce."""
        tipo = self.cleaned_data['tipo']
        if tipo not in {CalculoOperacion.TIPO_COMPRA, CalculoOperacion.TIPO_VENTA}:
            raise forms.ValidationError('El tipo de operación no es válido.')
        return tipo

    def _resolver_divisa(self, valor):
        """Resuelve una divisa activa o la representación base PYG."""
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_divisa_origen(self):
        """Resuelve y valida la divisa de origen."""
        return self._resolver_divisa(self.cleaned_data['divisa_origen'])

    def clean_divisa_destino(self):
        """Resuelve y valida la divisa de destino."""
        return self._resolver_divisa(self.cleaned_data['divisa_destino'])

    def clean(self):
        """Impide monedas iguales y valida el sentido de compra o venta."""
        cleaned_data = super().clean()
        tipo = cleaned_data.get('tipo')
        origen = cleaned_data.get('divisa_origen')
        destino = cleaned_data.get('divisa_destino')
        if origen and destino and origen.codigo == destino.codigo:
            raise forms.ValidationError('La divisa de origen y destino deben ser diferentes.')
        if tipo == CalculoOperacion.TIPO_COMPRA and destino and destino.codigo != 'PYG':
            raise forms.ValidationError('En una compra la divisa de destino debe ser PYG.')
        if tipo == CalculoOperacion.TIPO_VENTA and origen and origen.codigo != 'PYG':
            raise forms.ValidationError('En una venta la divisa de origen debe ser PYG.')
        if tipo in {CalculoOperacion.TIPO_COMPRA, CalculoOperacion.TIPO_VENTA}:
            moneda_extranjera = origen if tipo == CalculoOperacion.TIPO_COMPRA else destino
            if moneda_extranjera and moneda_extranjera.codigo == 'PYG':
                raise forms.ValidationError('Debe seleccionar una divisa extranjera para la operación.')
        return cleaned_data


