    divisa_destino = forms.ChoiceField(
        label='Divisa destino',
        choices=[],
        widget=forms.Select(attrs={'class': 'form-select ge-form-control'}),
    )

    @staticmethod
    def _divisa_guarani_implicit():
        """Construye la divisa PYG implícita cuando no existe en la base."""
        return Divisa(codigo='PYG', nombre='Guaraní', simbolo='₲', activa=True)

    @classmethod
    def opciones_divisas(cls, excluir=None):
        """Devuelve divisas activas excluyendo la elegida en el otro campo."""
        divisas_activas = list(Divisa.objects.filter(activa=True).order_by('codigo'))
        opciones = [('', 'Seleccione una divisa')]

        for divisa in divisas_activas:
            valor = 'PYG' if divisa.codigo == 'PYG' else str(divisa.pk)
            if valor != str(excluir):
                opciones.append((valor, f'{divisa.nombre} ({divisa.codigo})'))

        if excluir != 'PYG' and not any(opt[0] == 'PYG' for opt in opciones):
            opciones.insert(1, ('PYG', 'Guaraní (PYG)'))

        return opciones

    def __init__(self, *args, **kwargs):
        """Inicializa el formulario con las opciones vigentes de divisas."""
        super().__init__(*args, **kwargs)
        origen = self.data.get('divisa_origen') if self.is_bound else None
        destino = self.data.get('divisa_destino') if self.is_bound else None
        self.fields['divisa_origen'].choices = self.opciones_divisas(excluir=destino)
        self.fields['divisa_destino'].choices = self.opciones_divisas(excluir=origen)

    def clean_tipo(self):
        """Valida que la simulación sea compra, venta o cruce."""
        tipo = self.cleaned_data.get('tipo')
        if not tipo:
            raise forms.ValidationError('Debe seleccionar el tipo de operación.')
        if tipo not in {CalculoOperacion.TIPO_COMPRA, CalculoOperacion.TIPO_VENTA, CalculoOperacion.TIPO_CRUCE}:
            raise forms.ValidationError('El tipo de operación no es válido.')
        return tipo

    def clean_divisa_origen(self):
        """Convierte y valida la divisa seleccionada como origen."""
        valor = self.cleaned_data['divisa_origen']
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_divisa_destino(self):
        """Convierte y valida la divisa seleccionada como destino."""
        valor = self.cleaned_data['divisa_destino']
        if valor == 'PYG':
            return self._divisa_guarani_implicit()
        divisa = Divisa.objects.filter(pk=valor, activa=True).first()
        if not divisa:
            raise forms.ValidationError('Debe elegir una divisa válida.')
        return divisa

    def clean_monto(self):
        """Verifica que el monto de conversión sea positivo."""
        monto = self.cleaned_data['monto']
        if monto <= 0:
            raise forms.ValidationError('El monto debe ser mayor que cero.')
        return monto

    def clean(self):
        """Evita que la conversión use la misma divisa en ambos extremos."""
        cleaned_data = super().clean()
        origen = cleaned_data.get('divisa_origen')
        destino = cleaned_data.get('divisa_destino')

        if origen and destino:
            if getattr(origen, 'codigo', None) == getattr(destino, 'codigo', None):
                raise forms.ValidationError('La divisa de origen y destino deben ser diferentes.')
        tipo = cleaned_data.get('tipo')
        if tipo == CalculoOperacion.TIPO_COMPRA and destino and destino.codigo != 'PYG':
            raise forms.ValidationError('En una compra la divisa de destino debe ser PYG.')
        if tipo == CalculoOperacion.TIPO_VENTA and origen and origen.codigo != 'PYG':
            raise forms.ValidationError('En una venta la divisa de origen debe ser PYG.')
        if tipo == CalculoOperacion.TIPO_CRUCE and origen and destino and ('PYG' in {origen.codigo, destino.codigo}):
            raise forms.ValidationError('En un cruce debe seleccionar dos divisas extranjeras.')

        return cleaned_data


