def _obtener_cotizacion_operacion(divisa):
    """Obtiene compra y venta vigentes de una divisa o tasas unitarias de PYG."""
    if divisa.codigo == 'PYG':
        return Decimal('1.00'), Decimal('1.00'), None
    cotizacion = divisa.ultima_cotizacion
    if not cotizacion:
        raise ValueError(f'La divisa {divisa.codigo} no tiene cotización disponible.')
    return cotizacion.tasa_compra, cotizacion.tasa_venta, cotizacion


def _liquidar_operacion(tipo, monto, origen, destino, configuracion):
    """Liquida compra, venta o cruce aplicando PYG como moneda pivote."""
    compra_origen, venta_origen, _ = _obtener_cotizacion_operacion(origen)
    compra_destino, venta_destino, _ = _obtener_cotizacion_operacion(destino)

    if tipo == CalculoOperacion.TIPO_COMPRA:
        monto_pyg_bruto = monto * compra_origen
        tasa_origen = compra_origen
        tasa_destino = Decimal('1')
    elif tipo == CalculoOperacion.TIPO_VENTA:
        monto_pyg_bruto = monto
        tasa_origen = Decimal('1')
        tasa_destino = venta_destino
    else:
        monto_pyg_bruto = monto * compra_origen
        tasa_origen = compra_origen
        tasa_destino = venta_destino

    monto_pyg_bruto = monto_pyg_bruto.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    porcentaje = configuracion.comision_porcentaje
    comision_porcentual = (monto_pyg_bruto * porcentaje / Decimal('100')).quantize(
        Decimal('0.01'), rounding=ROUND_HALF_UP
    )
    comision_fija = configuracion.comision_monto_fijo_pyg or Decimal('0')
    comision = (comision_porcentual + comision_fija).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    monto_pyg_neto = (monto_pyg_bruto - comision).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if monto_pyg_neto < 0:
        raise ValueError('La comisión supera el importe de la operación.')

    if tipo == CalculoOperacion.TIPO_COMPRA:
        monto_final = monto_pyg_neto
    else:
        monto_final = (monto_pyg_neto / tasa_destino).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    tasa_aplicada = (monto_final / monto if monto else Decimal('0')).quantize(
        Decimal('0.000001'), rounding=ROUND_HALF_UP
    )
    return {
        'tasa_aplicada': tasa_aplicada,
        'tasa_origen': tasa_origen,
        'tasa_destino': tasa_destino,
        'comision': comision,
        'monto_pyg_bruto': monto_pyg_bruto,
        'monto_pyg_neto': monto_pyg_neto,
        'monto_final': monto_final,
    }


